import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.CsvSource;

@ParameterizedTest(name = "\"{0}\" -> valid={1}")
@CsvSource({
    "abcd1234, true",
    "abc,      false",
    "'',       false"      // quoted empty string
})
void validatesPassword(String pw, boolean expected) {
    assertEquals(expected, validator.isValid(pw)); // bool auto-converted
}

// null case via nullValues
@ParameterizedTest
@CsvSource(value = {"null, false", "abcd1234, true"}, nullValues = "null")
void handlesNull(String pw, boolean expected) {
    assertEquals(expected, validator.isValid(pw));
}
