// Rule: age must be in [18, 65] inclusive to be eligible
@ParameterizedTest(name = "age {0} -> eligible={1}")
@CsvSource({
    "17, false",   // min - 1  (just below)
    "18, true",    // min      (lower edge)
    "40, true",    // mid      (clearly valid)
    "65, true",    // max      (upper edge)
    "66, false"    // max + 1  (just above)
})
void checksAgeEligibility(int age, boolean expected) {
    assertEquals(expected, policy.isEligible(age));
}

// Special cases worth their own rows: 0, negative, Integer.MAX_VALUE
