import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.*;
import java.util.stream.Stream;

@ParameterizedTest
@MethodSource("discountScenarios")
void appliesDiscount(Customer customer, Order order, double expected) {
    assertEquals(expected, pricingService.finalPrice(order, customer));
}

// Factory: static, returns Stream<Arguments>
static Stream<Arguments> discountScenarios() {
    return Stream.of(
        Arguments.of(new Customer(PREMIUM), new Order(100.0), 90.0),
        Arguments.of(new Customer(REGULAR), new Order(100.0), 100.0),
        Arguments.of(new Customer(PREMIUM), new Order(0.0),   0.0)
    );
}

// Reference a factory in another class by fully-qualified name:
// @MethodSource("com.example.TestData#discountScenarios")
